// Filtra apenas conversas onde a última mensagem foi enviada pelo Agente/IA
// e calcula o tempo de inatividade em horas
const items = $input.all();
const results = [];
const now = new Date().getTime();

for (const item of items) {
  const payload = item.json.data || item.json;
  const conversations = Array.isArray(payload) ? payload : (payload.payload || []);

  for (const conv of conversations) {
    // Se status for 'open', humano está atendendo. Ignora.
    if (conv.status === 'open') continue;

    const lastActivity = (conv.last_activity_at || conv.updated_at) * 1000;
    const diffHours = (now - lastActivity) / (1000 * 60 * 60);
    const followCount = conv.custom_attributes?.followup_count || 0;

    let stage = 0;
    if (diffHours >= 72 && followCount === 2) {
      stage = 3; // Break-up final
    } else if (diffHours >= 24 && followCount === 1) {
      stage = 2; // Prova de valor
    } else if (diffHours >= 2 && followCount === 0) {
      stage = 1; // Lembrete gentil
    }

    if (stage > 0) {
      results.push({
        json: {
          conversation_id: conv.id,
          contact_name: conv.meta?.sender?.name || 'Cliente',
          phone_number: conv.meta?.sender?.phone_number || '',
          followup_stage: stage,
          diff_hours: diffHours.toFixed(1)
        }
      });
    }
  }
}

return results;

